<?php
namespace Tests\Feature;
use Tests\TestCase;
use App\Onenew\AiOperations\SourceTools;
use App\Onenew\AiOperations\RepoSettings;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Facades\Cache;
use Illuminate\Foundation\Testing\RefreshDatabase;
final class SourceToolsTest extends TestCase
{
 use RefreshDatabase;
 private function tools():SourceTools {return new SourceTools(app(RepoSettings::class),['repository'=>sys_get_temp_dir().'/onenew-source-tests','runtime'=>sys_get_temp_dir().'/onenew-source-tests']);}
 protected function setUp():void {parent::setUp();$root=sys_get_temp_dir().'/onenew-source-tests';@mkdir($root.'/app',0777,true);file_put_contents($root.'/REVISION',str_repeat('a',40));file_put_contents($root.'/app/Example.php',"<?php\nreturn 'safe';\n");}
 public function test_reads_actual_source_with_lines_and_hash():void {$r=$this->tools()->read('source.read',['source'=>'runtime','path'=>'app/Example.php','start_line'=>2]);self::assertSame("return 'safe';\n",$r['content']);self::assertTrue($r['read_only']);self::assertSame(str_repeat('a',40),$r['revision']);}
 public function test_traversal_private_binary_and_runtime_edit_paths_are_rejected():void {Http::preventStrayRequests();foreach(['../app/Example.php','app/Example.php?ref=evil.php','app/Example%2f.php','app/../app/Example.php','app/.env','app/storage/foo.php','app/vendor/foo.php','app/foo.lock','app/foo.php/../../x.php'] as $path){try{$this->tools()->read('source.read',['path'=>$path]);self::fail($path);}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){self::assertSame(422,$e->getStatusCode());}}try{$this->tools()->propose(1,[['path'=>'app/Example.php','old_text'=>'safe','new_text'=>'new']]);self::fail('runtime patch accepted');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){self::assertSame(422,$e->getStatusCode());}Http::assertNothingSent();}
 public function test_proposal_uses_fixed_revision_and_exact_unique_text():void {Http::fake(['api.github.com/*'=>Http::response(['encoding'=>'base64','size'=>20,'content'=>base64_encode('unique old content')])]);$p=$this->tools()->propose(10,[['path'=>'customizations/onenew/ai-operations/app/Example.php','old_text'=>'old','new_text'=>'new']]);self::assertSame('unique new content',$p['patches'][0]['after']);Http::assertSent(fn($r)=>$r->url()==='https://api.github.com/repos/chinahch/onenew/contents/customizations/onenew/ai-operations/app/Example.php?ref='.str_repeat('a',40));$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);$this->tools()->propose(10,[['path'=>'customizations/onenew/ai-operations/app/Example.php','old_text'=>'missing','new_text'=>'new']]);}
 public function test_duplicate_old_text_and_secret_insertion_are_rejected():void {Http::fake(['api.github.com/*'=>Http::response(['encoding'=>'base64','size'=>7,'content'=>base64_encode('old old')])]);foreach([['old_text'=>'old','new_text'=>'new'],['old_text'=>'old','new_text'=>'github_pat_abcdef123456']] as $patch){try{$this->tools()->propose(1,[['path'=>'customizations/onenew/ai-operations/app/Example.php']+$patch]);self::fail('unsafe patch');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){self::assertContains($e->getStatusCode(),[409,422]);}}}
 public function test_binary_and_symlink_reads_are_rejected():void {$root=sys_get_temp_dir().'/onenew-source-tests';file_put_contents($root.'/app/Binary.php',"a\0b");try{$this->tools()->read('source.read',['source'=>'runtime','path'=>'app/Binary.php']);self::fail('binary accepted');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){self::assertSame(422,$e->getStatusCode());}if(@symlink($root.'/app/Example.php',$root.'/app/Link.php')){try{$this->tools()->read('source.read',['source'=>'runtime','path'=>'app/Link.php']);self::fail('link accepted');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){self::assertSame(422,$e->getStatusCode());}finally{unlink($root.'/app/Link.php');}}}
 public function test_installed_overlay_paths_list_read_search_and_migrations():void {
  $root=sys_get_temp_dir().'/onenew-source-tests';@mkdir($root.'/ai-operations/app',0777,true);@mkdir($root.'/ai-operations/database/migrations',0777,true);@mkdir($root.'/ai-operations/database/private',0777,true);
  file_put_contents($root.'/ai-operations/app/Overlay.php','<?php return "actual overlay";');file_put_contents($root.'/ai-operations/database/migrations/2026_test.php','<?php // migration source');file_put_contents($root.'/ai-operations/database/private/state.php','private-secret');file_put_contents($root.'/ai-operations/app/credentials.php','raw-credential-secret');file_put_contents($root.'/ai-operations/app/.env','raw-env-secret');
  $path='customizations/onenew/ai-operations/app/Overlay.php';$r=$this->tools()->read('source.read',['path'=>$path]);self::assertSame('<?php return "actual overlay";',$r['content']);
  $list=$this->tools()->read('source.list',['path'=>'customizations/onenew/ai-operations/']);self::assertContains($path,array_column($list['items'],'path'));$json=json_encode($list);self::assertStringNotContainsString('credentials.php',$json);self::assertStringNotContainsString('.env',$json);self::assertStringNotContainsString('private/state.php',$json);
  $search=$this->tools()->read('source.search',['query'=>'actual overlay']);self::assertContains($path,array_column($search['items'],'path'));
  $migration=$this->tools()->read('source.read',['path'=>'customizations/onenew/ai-operations/database/migrations/2026_test.php']);self::assertSame('<?php // migration source',$migration['content']);
  foreach(['customizations/onenew/ai-operations/app/credentials.php','customizations/onenew/ai-operations/app/.env','customizations/onenew/ai-operations/database/private/state.php'] as $denied){try{$this->tools()->read('source.read',['path'=>$denied]);self::fail('secret file read');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){self::assertSame(422,$e->getStatusCode());}}
 }
 public function test_single_long_line_read_is_byte_bounded():void {$root=sys_get_temp_dir().'/onenew-source-tests';file_put_contents($root.'/app/Long.php',str_repeat('界',30000));$r=$this->tools()->read('source.read',['source'=>'runtime','path'=>'app/Long.php']);self::assertLessThanOrEqual(12000,strlen($r['content']));self::assertSame(1,preg_match('//u',$r['content']));}
 public function test_repository_key_is_encrypted_retained_and_never_returned():void {$s=app(RepoSettings::class);$r=$s->save(['repo_key'=>'github_pat_fixture']);self::assertTrue($r['key_configured']);self::assertStringNotContainsString('github_pat_fixture',json_encode($r));self::assertSame('github_pat_fixture',$s->token());$s->save(['api_key'=>'']);self::assertSame('github_pat_fixture',$s->token());$s->save(['clear_key'=>true]);self::assertSame('',$s->token());}
 public function test_publish_retries_existing_branch_and_pr_and_is_admin_owned():void {$s=app(RepoSettings::class);$s->save(['api_key'=>'fixture-key']);Http::fake(function($r){$url=$r->url();if(str_contains($url,'/contents/'))return Http::response(['encoding'=>'base64','size'=>3,'content'=>base64_encode('old')]);if(str_contains($url,'/git/ref/'))return Http::response(['object'=>['sha'=>str_repeat('c',40)]]);if(str_contains($url,'/pulls'))return Http::response([['number'=>123]]);return Http::response([],500);});$p=$this->tools()->propose(10,[['path'=>'customizations/onenew/ai-operations/app/Example.php','old_text'=>'old','new_text'=>'new']]);$cacheKey='onenew:ai:patch:10:'.$p['id'];$stored=json_decode(\Illuminate\Support\Facades\Crypt::decryptString(Cache::get($cacheKey)),true);$stored['commit_sha']=str_repeat('c',40);Cache::put($cacheKey,\Illuminate\Support\Facades\Crypt::encryptString(json_encode($stored)),600);$id=(string)\Illuminate\Support\Str::uuid();$result=$this->tools()->publish(10,$p['id'],$id);self::assertSame('https://github.com/chinahch/onenew/pull/123',$result['pull_request_url']);self::assertSame($result,$this->tools()->publish(10,$p['id'],$id));Http::assertNotSent(fn($r)=>$r->method()==='POST');$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);$this->tools()->publish(11,$p['id'],$id);}
}
